-- Schema for the AI-first integration platform. Postgres 16.
-- Becomes the first Drizzle migration in Phase 0 (packages/db).
-- Access rule: every table carries org_id. Every query goes through the data
-- layer (packages/db/repo/*), which takes the caller's org_id and checks the
-- role. No query is written without it. RLS is a later hardening step.
-- Times are timestamptz in UTC. Ids are uuid v7-style from gen_random_uuid().
-- Auth tables (user, session, account, verification) are owned by Better Auth
-- and generated by its CLI. "users" below is that table.

create extension if not exists pgcrypto;

-- ── tenancy ────────────────────────────────────────────────────────────────

create table orgs (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  slug text not null unique,
  plan text not null default 'free' check (plan in ('free','team','business')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table memberships (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references orgs(id) on delete cascade,
  user_id uuid not null references users(id) on delete cascade,
  role text not null check (role in ('admin','developer','monitor','viewer')),
  created_at timestamptz not null default now(),
  unique (org_id, user_id)
);
create index on memberships (user_id);

create table projects (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references orgs(id) on delete cascade,
  name text not null,
  identifier text not null,
  description text not null default '',
  created_by uuid references users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (org_id, identifier)
);

-- ── connections ────────────────────────────────────────────────────────────

create table agent_groups (                       -- Phase 9: on-prem agent
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references orgs(id) on delete cascade,
  name text not null,
  identifier text not null,
  last_heartbeat_at timestamptz,
  created_at timestamptz not null default now(),
  unique (org_id, identifier)
);

create table connections (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references orgs(id) on delete cascade,
  project_id uuid references projects(id) on delete cascade,   -- null = shared across projects
  name text not null,
  identifier text not null,
  adapter text not null,                          -- 'rest' | 'soap' | 'sftp' | 'postgres' | ...
  adapter_version text not null default '1',
  role text not null check (role in ('trigger','invoke','trigger_invoke')),
  properties jsonb not null default '{}',         -- non-secret config: baseUrl, host, port...
  auth_type text not null default 'none'
    check (auth_type in ('none','basic','api_key','bearer','oauth_client_credentials','oauth_authorization_code')),
  secret_ciphertext bytea,                        -- AES-256-GCM envelope; never returned by the API, never sent to the model
  secret_key_id text,
  agent_group_id uuid references agent_groups(id) on delete set null,
  status text not null default 'draft' check (status in ('draft','configured','failed')),
  last_tested_at timestamptz,
  last_test_error text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (org_id, identifier)
);
create index on connections (project_id);
create index on connections (agent_group_id);

-- ── design time ────────────────────────────────────────────────────────────

create table integrations (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references orgs(id) on delete cascade,
  project_id uuid not null references projects(id) on delete cascade,
  name text not null,
  identifier text not null,
  version text not null default '01.00.0000',
  style text not null check (style in ('application','scheduled')),
  status text not null default 'draft'
    check (status in ('draft','configured','activating','active','failed','inactive')),
  definition jsonb not null,                      -- the flow, validated by packages/flow-schema
  definition_hash text not null,                  -- detects edits between AI proposal and apply
  tracing_level text not null default 'production' check (tracing_level in ('production','audit','debug')),
  trigger_path text,                              -- '/t/{org}/{identifier}/{version}' for application style
  locked_by uuid references users(id) on delete set null,
  locked_at timestamptz,
  activated_at timestamptz,
  activated_by uuid references users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (org_id, identifier, version)
);
create index on integrations (project_id);
create index on integrations (org_id, status);
create unique index on integrations (trigger_path) where status = 'active';

create table schedules (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references orgs(id) on delete cascade,
  integration_id uuid not null unique references integrations(id) on delete cascade,
  kind text not null check (kind in ('interval','cron')),
  expression text not null,                       -- 'PT15M' or a cron expression
  timezone text not null default 'UTC',           -- IANA name; next_run_at computed in this zone
  start_at timestamptz,
  end_at timestamptz,
  status text not null default 'active' check (status in ('active','paused')),
  allow_overlap boolean not null default false,
  next_run_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index on schedules (status, next_run_at);

create table lookups (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references orgs(id) on delete cascade,
  project_id uuid references projects(id) on delete cascade,
  name text not null,
  domains text[] not null check (array_length(domains, 1) >= 2),
  rows jsonb not null default '[]',               -- [["US","USA"],["IN","IND"]]
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (org_id, name)
);

create table libraries (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references orgs(id) on delete cascade,
  project_id uuid references projects(id) on delete cascade,
  name text not null,
  version text not null default '1',
  source text not null,                           -- JS, run in an isolate, no network
  functions jsonb not null default '[]',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (org_id, name, version)
);

-- ── run time ───────────────────────────────────────────────────────────────

create table instances (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references orgs(id) on delete cascade,
  integration_id uuid not null references integrations(id) on delete cascade,
  integration_version text not null,
  status text not null default 'queued'
    check (status in ('queued','running','succeeded','failed','aborted')),
  trigger_kind text not null check (trigger_kind in ('request','schedule','resubmit','dry_run','manual')),
  parent_instance_id uuid references instances(id) on delete set null,   -- resubmit chain
  idempotency_key text,
  primary_business_id text,                       -- searchable (S21)
  business_ids jsonb not null default '{}',
  recoverable boolean not null default false,
  error_code text,
  error_message text,
  started_at timestamptz,
  ended_at timestamptz,
  duration_ms integer,
  created_at timestamptz not null default now()
);
create index on instances (org_id, created_at desc);
create index on instances (integration_id, created_at desc);
create index on instances (org_id, status, created_at desc);
create index on instances (org_id, primary_business_id);
create index on instances (parent_instance_id);
create unique index on instances (integration_id, idempotency_key) where idempotency_key is not null;

create table instance_steps (
  id uuid primary key default gen_random_uuid(),
  instance_id uuid not null references instances(id) on delete cascade,
  seq integer not null,
  node_id text not null,
  node_type text not null,
  iteration integer,                              -- for-each / while index
  status text not null check (status in ('running','succeeded','failed','skipped')),
  input_ref text,                                 -- object storage key; null when tracing is 'production'
  output_ref text,
  message text,
  started_at timestamptz not null default now(),
  ended_at timestamptz,
  unique (instance_id, seq)
);

-- ── AI builder ─────────────────────────────────────────────────────────────

create table ai_sessions (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references orgs(id) on delete cascade,
  user_id uuid not null references users(id) on delete cascade,
  project_id uuid references projects(id) on delete cascade,
  integration_id uuid references integrations(id) on delete set null,
  title text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index on ai_sessions (org_id, user_id, updated_at desc);

create table ai_messages (
  id uuid primary key default gen_random_uuid(),
  session_id uuid not null references ai_sessions(id) on delete cascade,
  role text not null check (role in ('user','assistant','tool')),
  content jsonb not null,                         -- provider-native blocks, incl. tool_use / tool_result
  model text,
  input_tokens integer,
  output_tokens integer,
  created_at timestamptz not null default now()
);
create index on ai_messages (session_id, created_at);

create table ai_changes (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references orgs(id) on delete cascade,
  session_id uuid not null references ai_sessions(id) on delete cascade,
  integration_id uuid references integrations(id) on delete cascade,   -- null until a new integration is created
  base_hash text,                                 -- definition_hash the proposal was built on
  proposed_definition jsonb not null,
  diff jsonb not null,
  summary text not null,
  status text not null default 'proposed'
    check (status in ('proposed','accepted','partially_accepted','rejected','stale')),
  validation_errors jsonb not null default '[]',
  decided_by uuid references users(id) on delete set null,
  decided_at timestamptz,
  created_at timestamptz not null default now()
);
create index on ai_changes (integration_id, created_at desc);
create index on ai_changes (session_id);

-- ── events, notifications, Hermes ──────────────────────────────────────────

-- Transactional outbox. Every state change writes a row in the same
-- transaction; the dispatcher fans it out to SSE, webhooks and MCP.
create table events (
  id bigint generated always as identity primary key,  -- monotonic cursor for list_events(since)
  org_id uuid not null references orgs(id) on delete cascade,
  type text not null,                             -- 'integration.activated', 'instance.failed', 'ai.change.proposed', ...
  subject_type text not null,
  subject_id uuid not null,
  severity text not null default 'info' check (severity in ('info','warning','error')),
  summary text not null,                          -- one human line, ready to post to Telegram/Slack
  data jsonb not null default '{}',
  created_at timestamptz not null default now()
);
create index on events (org_id, id);
create index on events (org_id, type, id);

create table notification_channels (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references orgs(id) on delete cascade,
  kind text not null check (kind in ('webhook','slack_webhook','telegram_bot','email')),
  name text not null,
  config_ciphertext bytea not null,               -- URL / bot token / chat id, encrypted
  event_types text[] not null default '{*}',
  min_severity text not null default 'info' check (min_severity in ('info','warning','error')),
  enabled boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index on notification_channels (org_id);

create table deliveries (
  id uuid primary key default gen_random_uuid(),
  event_id bigint not null references events(id) on delete cascade,
  channel_id uuid not null references notification_channels(id) on delete cascade,
  status text not null default 'pending' check (status in ('pending','sent','failed')),
  attempts integer not null default 0,
  last_error text,
  next_attempt_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  unique (event_id, channel_id)                   -- idempotent fan-out
);
create index on deliveries (status, next_attempt_at);

create table api_keys (                           -- used by the public API and by Hermes over MCP
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references orgs(id) on delete cascade,
  name text not null,
  prefix text not null unique,                    -- shown in UI: 'oicr_ab12'
  hash text not null,                             -- sha256 of the full key
  scopes text[] not null default '{read}',        -- read | build | operate (activate, resubmit)
  last_used_at timestamptz,
  created_by uuid references users(id) on delete set null,
  revoked_at timestamptz,
  created_at timestamptz not null default now()
);
create index on api_keys (org_id);

-- ── metering ───────────────────────────────────────────────────────────────

create table usage_hourly (
  org_id uuid not null references orgs(id) on delete cascade,
  hour timestamptz not null,                      -- date_trunc('hour', ...) in UTC
  messages integer not null default 0,
  ai_input_tokens bigint not null default 0,
  ai_output_tokens bigint not null default 0,
  primary key (org_id, hour)
);
